#!/usr/bin/env python3
"""Report all scored outcomes without presenting partial repairs as successes."""
import html,itertools,json,statistics,sys
from pathlib import Path
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[1];OUT=HERE/'results'
sys.path.insert(0,str(ROOT/'benchmarks/fixed-budget'))
import report as style
NAMES={'handwork':'Updated Handwork','opencode':'OpenCode','codex':'Codex'}
CATEGORIES={'authorization':'Authorization','cache_isolation':'Cache isolation','invalidation':'Invalidation','regressions':'Regressions'}
def median(xs):return statistics.median(xs) if xs else None
def main():
 runs=json.loads((OUT/'attempts.json').read_text());assert len(runs)==15,'Wait for all attempts'
 state=json.loads((OUT/'state.json').read_text());summary={}
 for h in NAMES:
  rs=[r for r in runs if r['harness']==h];summary[h]={'successes':sum(r['success'] for r in rs),'attempts':len(rs),'timeouts':sum(r['timeout'] for r in rs),'median_peak_mib':median([r['peak_rss_bytes']['harness']/2**20 for r in rs]),'median_success_s':median([r['duration_s'] for r in rs if r['success']]),'categories':{c:sum(r['categories'][c] for r in rs) for c in CATEGORIES}}
  for metric in ['input_tokens','output_tokens','tool_calls','model_requests']:
   values=[r.get(metric) for r in rs];summary[h]['mean_'+metric]=statistics.mean(values) if all(v is not None for v in values) else None
 pairs=[]
 for a,b in itertools.combinations(NAMES,2):
  matched=[i for i in range(1,6) if all(next(r for r in runs if r['harness']==h and r['attempt']==i)['success'] for h in [a,b])]
  pairs.append({'a':a,'b':b,'attempts':matched,'a_median_s':median([r['duration_s'] for r in runs if r['harness']==a and r['attempt'] in matched]),'b_median_s':median([r['duration_s'] for r in runs if r['harness']==b and r['attempt'] in matched])})
 common=[i for i in range(1,6) if all(next(r for r in runs if r['harness']==h and r['attempt']==i)['success'] for h in NAMES)]
 for h in NAMES:summary[h]['matched_median_s']=median([r['duration_s'] for r in runs if r['harness']==h and r['attempt'] in common])
 data={'task':'tenant-cache','state':state,'summary':summary,'runs':runs,'matched_pairs':pairs,'common_success_attempts':common,'controls':json.loads((OUT/'controls.json').read_text()),'preflight':json.loads((OUT/'preflight.json').read_text()),'verifier_audit':json.loads((OUT/'verifier-audit.json').read_text())}
 (OUT/'report-data.json').write_text(json.dumps(data,indent=2))
 css=style.TEMPLATE.split('<style>',1)[1].split('</style>',1)[0]
 t,o,c=[summary[h] for h in NAMES];reduction=100*(1-t['median_peak_mib']/o['median_peak_mib'])
 headline=f"Updated Handwork completed {t['successes']} of 5 attempts versus {o['successes']} of 5 for OpenCode, while using {abs(reduction):.1f}% {'less' if reduction>=0 else 'more'} harness memory."
 page=TEMPLATE.replace('__CSS__',css).replace('__HEADLINE__',html.escape(headline)).replace('__CODEX__',str(c['successes'])).replace('__DATA__',json.dumps(data).replace('</','<\\/'))
 (ROOT/'tenant-cache-benchmark-results.html').write_text(page)
 print(json.dumps({'summary':summary,'matched_pairs':pairs},indent=2))
TEMPLATE='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Handwork · Organization isolation benchmark</title><style>__CSS__ .panel{min-width:0} .matrix th{white-space:normal;min-width:100px} .matrix td{text-align:center}.matrix th:first-child,.matrix td:first-child{text-align:left}.chart-row strong{overflow-wrap:anywhere}</style><main>
<header><div class="brand">handwork.</div><span class="badge">AUTHORIZATION + CACHING</span></header>
<div class="hero"><div class="tag">Harness lab / 003 · fresh competitor runs</div><h1>__HEADLINE__</h1><p class="intro">Codex completed __CODEX__ of 5. Complete success requires every independent check, existing tests and protected-file checks to pass within budget. A partial security fix is a failed task.</p><div class="meta"><span>18 TypeScript source files</span><span>GPT-6 Astra · low reasoning</span><span>10 minutes per attempt</span><span>3 harnesses × 5 fresh attempts</span></div></div>
<div class="cards" id="cards"></div>
<section class="panel"><h2>Diagnostic results</h2><p>Categories explain failures; they do not grant partial task success. Each cell counts attempts passing every check in that category.</p><div class="table-wrap"><table><thead><tr><th>Harness</th><th>Complete success</th><th>Authorization</th><th>Cache isolation</th><th>Invalidation</th><th>Regressions</th></tr></thead><tbody id="categories"></tbody></table></div></section>
<section class="panel"><div class="section-top"><div><h2>Correctness first. Then compare resources.</h2><p>Completion times use rounds solved by all three harnesses. Pairwise matched results remain available below. All outcomes count toward resource averages.</p></div><label>Metric <select id="metric"><option value="memory">Peak harness memory</option><option value="time">Matched completion time</option><option value="input">Input tokens</option><option value="output">Output tokens</option><option value="tools">Tool calls</option><option value="requests">Model requests</option></select></label></div><div id="chart"></div><p class="small" id="chart-note"></p><div class="small" id="pairs"></div></section>
<section class="panel"><div class="section-top"><h2>All 15 attempts</h2><button id="download">Download results JSON</button></div><div class="table-wrap"><table><thead><tr><th>Order</th><th>Harness</th><th>Result</th><th>Time</th><th>Harness RSS</th><th>Test RSS</th><th>Input / output</th><th>Tools</th><th>Requests</th><th>Evidence</th></tr></thead><tbody id="runs"></tbody></table></div></section>
<section class="panel"><h2>The verifier was tested first</h2><p>Only the complete control patch passes all independent checks. The authorization-only and cache-only controls demonstrate partial repairs. Disabling the cache must fail cache-use checks; clearing all caches must fail preservation of unrelated cache hits. Correct control patches remain private.</p><div class="table-wrap"><table><thead><tr><th>Control</th><th>Independent checks</th><th>Existing tests</th></tr></thead><tbody id="controls"></tbody></table></div><p class="small">A post-run audit removed an unnecessary assertion that denied requests could not increment cache-read counters. Stored data and cache entries must remain unchanged; harmless reads are allowed. All six original controls and all fifteen attempts were rechecked, with no changed outcomes. An additional correct control with a harmless cache read also passed. <a href="benchmarks/tenant-cache/results/verifier-audit.json">Verifier audit</a></p><details><summary>Control diagnostics</summary><pre id="control-details"></pre></details></section>
<section class="panel"><h2>Independent checks by attempt</h2><p>Fourteen deterministic checks plus the existing test suite cover owner-based authorization, organization separation, pagination/sorting, invalidation, revoked membership, useful caching, and normal API behavior.</p><div class="table-wrap"><table class="matrix"><thead id="matrix-head"></thead><tbody id="matrix"></tbody></table></div><details><summary>Failed checks and incomplete attempts</summary><pre id="failures"></pre></details></section>
<section class="panel"><h2>Protocol and measurement limits</h2><p>All binaries were frozen before fixture exposure. Updated Handwork uses the same optimized hash as the prior search test. Every attempt starts from the same broken commit, with a fresh session and repository. Dependencies were prepared before scoring; Node executes TypeScript directly. The fixture uses an in-memory database and an injected instrumented cache, with no network calls or sleeps.</p><p>Documentation specifies status codes and all required behavior. The sandbox denies verifier, control patches, benchmark source/results, sibling workspaces, earlier benchmark directories and user attachments. Inbound and loopback network connections are denied equally; provider network access is permitted. The report server is stopped during scoring.</p><p>Harness, test and other-tool RSS are sampled separately. Very brief peaks can be missed. Hosted model hardware and service load are uncontrolled. Five attempts on one fixture do not establish a general ranking. Codex is the app-bundled CLI plus code-mode helper; desktop UI and this orchestrator are excluded.</p><p>Input/output totals cover all reported model usage, including cached input and reported reasoning. OpenCode includes descendant sessions from its isolated database. Codex uses unique response IDs and tool call IDs from isolated parent/descendant rollouts. Handwork uses its fresh no-save mode, which does not create a persistent subagent host.</p><p>Model requests are separate from tool calls: Handwork counts provider admissions, OpenCode counts persisted model step starts, and Codex counts response IDs with usage records. Unbilled transport retries are not uniformly exposed. Native tool calls can contain multiple shell commands or code-mode operations; they are not a count of individual filesystem operations. No claims are made about model-server memory.</p><p id="order"></p><details><summary>Exact task prompt</summary><pre id="prompt"></pre></details><details><summary>Hardware, hashes and preflight</summary><pre id="metadata"></pre></details></section>
<footer><a href="benchmarks/tenant-cache/results/report-data.json">Raw results</a><a href="benchmarks/tenant-cache/results/prompt.txt">Task prompt</a><a href="benchmarks/tenant-cache/benchmark.py">Runner</a><a href="search-benchmark-results.html">Search benchmark</a></footer></main><script id="data" type="application/json">__DATA__</script><script>
const D=JSON.parse(document.getElementById('data').textContent),names={handwork:'Updated Handwork',opencode:'OpenCode',codex:'Codex'},keys=Object.keys(names),colors={handwork:'#20714c',opencode:'#687dd3',codex:'#ae7445'},categories=['authorization','cache_isolation','invalidation','regressions'];
const f=(v,n=1)=>v==null?'Unavailable':Number(v).toLocaleString('en-US',{minimumFractionDigits:n,maximumFractionDigits:n}),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
document.getElementById('cards').innerHTML=keys.map(h=>{const s=D.summary[h];return `<article class="card" style="--accent:${colors[h]}"><h2>${names[h]}</h2><div class="success">${s.successes} / 5 <small>complete fixes</small></div><div class="small">${f(s.successes/5*100,0)}% success · ${s.timeouts} timeouts</div><div class="stats"><div><strong>${f(s.median_peak_mib)} MiB</strong><span>Median peak harness RSS</span></div><div><strong>${f(s.matched_median_s)} s</strong><span>Median time, jointly solved rounds</span></div></div></article>`}).join('');
document.getElementById('categories').innerHTML=keys.map(h=>`<tr><td>${names[h]}</td><td>${D.summary[h].successes} / 5</td>${categories.map(c=>`<td>${D.summary[h].categories[c]} / 5</td>`).join('')}</tr>`).join('');
function draw(){const m=document.getElementById('metric').value,config={memory:['median_peak_mib',' MiB','Median of per-attempt peak harness RSS; all attempts.'],time:['matched_median_s',' s',`${D.common_success_attempts.length} rounds solved by all three harnesses.`],input:['mean_input_tokens',' tokens','Mean per attempt across all reported calls.'],output:['mean_output_tokens',' tokens','Mean per attempt across all reported calls.'],tools:['mean_tool_calls',' calls','Mean native tool invocations per attempt, including descendants.'],requests:['mean_model_requests',' requests','Mean observed model requests per attempt; see measurement definitions below.']}[m],values=keys.map(h=>({h,v:D.summary[h][config[0]]})),max=Math.max(1,...values.map(x=>x.v||0));document.getElementById('chart').innerHTML=values.map(({h,v})=>`<div class="chart-row"><strong>${names[h]}</strong><div class="track"><div class="bar" style="width:${v==null?0:v/max*100}%;background:${colors[h]}"></div></div><span class="value">${f(v)}${v==null?'':config[1]}</span></div>`).join('');document.getElementById('chart-note').textContent=config[2];}
document.getElementById('metric').addEventListener('change',draw);draw();
document.getElementById('pairs').innerHTML=D.matched_pairs.map(p=>`${names[p.a]} / ${names[p.b]}: ${p.attempts.length} matched successes; median ${f(p.a_median_s)} / ${f(p.b_median_s)} seconds.`).join('<br>');
const base='benchmarks/tenant-cache/results/';
document.getElementById('runs').innerHTML=D.runs.map(r=>`<tr><td>${r.attempt}.${r.position}</td><td>${names[r.harness]}</td><td class="${r.success?'pass':'fail'}">${r.timeout?'Timeout':r.success?'Pass':'Fail'}</td><td>${f(r.duration_s)}s</td><td>${f(r.peak_rss_bytes.harness/2**20)} MiB</td><td>${f(r.peak_rss_bytes.tests/2**20)} MiB</td><td>${f(r.input_tokens,0)} / ${f(r.output_tokens,0)}</td><td>${f(r.tool_calls,0)}</td><td>${f(r.model_requests,0)}</td><td><a href="${base}${r.log}.diff">diff</a> · <a href="${base}${r.log}.stdout">log</a> · <a href="${base}${r.log}.verify.stdout">checks</a> · <a href="${base}${r.log}.existing.stdout">tests</a> · <a href="${base}${r.log}.added-files.json">added files</a></td></tr>`).join('');
document.getElementById('controls').innerHTML=Object.entries(D.controls).map(([k,v])=>`<tr><td>${k.replaceAll('_',' ')}</td><td>${v.checks.filter(c=>c.pass).length} / ${v.checks.length}</td><td>${v.existing_tests_pass?'Pass':'Fail'}</td></tr>`).join('');
document.getElementById('control-details').textContent=JSON.stringify(D.controls,null,2);
const labels=[...D.controls.complete.checks.map(c=>c.name),'Existing regression tests'];
document.getElementById('matrix-head').innerHTML='<tr><th>Attempt</th>'+labels.map(l=>`<th>${esc(l)}</th>`).join('')+'</tr>';
document.getElementById('matrix').innerHTML=D.runs.map(r=>`<tr><td>${names[r.harness]} ${r.attempt}</td>${labels.map(l=>{const c=r.checks.find(x=>x.name===l);return `<td class="${c?.pass?'pass':'fail'}">${c?.pass?'Pass':c?'Fail':'Unavailable'}</td>`}).join('')}</tr>`).join('');
document.getElementById('failures').textContent=JSON.stringify(D.runs.filter(r=>!r.success).map(r=>({harness:r.harness,attempt:r.attempt,timeout:r.timeout,protected_files_unchanged:r.protected_files_unchanged,accounting_error:r.accounting_error,checks:r.checks.filter(c=>!c.pass)})),null,2);
document.getElementById('order').textContent=D.state.orders.map((o,i)=>`Round ${i+1}: ${o.map(h=>names[h]).join(' → ')}`).join('; ');
document.getElementById('prompt').textContent=D.state.prompt;
document.getElementById('metadata').textContent=JSON.stringify({created:D.state.created,freeze:D.state.frozen_at,commit:D.state.commit,machine:D.state.machine,model:D.state.model,reasoning:D.state.reasoning,context:D.state.context,binaries:D.state.binaries,codex_runtime:D.state.codex_runtime,preflight:D.preflight},null,2);
document.getElementById('download').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(D,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=u;a.download='tenant-cache-benchmark.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);};
</script></html>'''
if __name__=='__main__':main()
